### Minimal secure Flask-Login + Argon2 login

```python
# app.py
import os
import redis
from flask import Flask, render_template, request, redirect, url_for, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import (
    LoginManager, UserMixin, login_user, logout_user,
    login_required, current_user
)
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from flask_argon2 import Argon2

app = Flask(__name__)

app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # do NOT hard-code 'my_secret_key' / 'secret_key'
    SQLALCHEMY_DATABASE_URI="sqlite:///budget_tracker.db",
    SQLALCHEMY_TRACK_MODIFICATIONS=False,
    WTF_CSRF_ENABLED=True,
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=os.environ.get("FLASK_ENV") == "production",

    # Argon2 settings you discussed for benchmarking:
    ARGON2_TIME_COST=3,
    ARGON2_MEMORY_COST=65536,
    ARGON2_PARALLELISM=2,
)

db = SQLAlchemy(app)
argon2 = Argon2(app)

login_manager = LoginManager(app)
login_manager.login_view = "login"
login_manager.login_message_category = "warning"

redis_client = redis.Redis(
    host="localhost",
    port=6379,
    db=0,
    decode_responses=True,
)

MAX_ATTEMPTS = 5
LOCKOUT_SECONDS = 60 * 60  # one hour


class User(UserMixin, db.Model):
    __tablename__ = "users"

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False, index=True)
    password_hash = db.Column(db.String(255), nullable=False)
    role = db.Column(db.String(20), nullable=False, default="user")


class LoginForm(FlaskForm):
    username = StringField(
        "Username",
        validators=[DataRequired(), Length(max=80)],
    )
    password = PasswordField(
        "Password",
        validators=[DataRequired(), Length(min=1, max=1024)],
    )
    submit = SubmitField("Log in")


class RegisterForm(FlaskForm):
    username = StringField(
        "Username",
        validators=[DataRequired(), Length(min=3, max=80)],
    )
    password = PasswordField(
        "Password",
        validators=[DataRequired(), Length(min=8, max=1024)],
    )
    submit = SubmitField("Register")


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


def _lockout_key(username: str) -> str:
    return f"lockout:{username.lower()}"


def _attempt_key(username: str) -> str:
    return f"attempt:{username.lower()}"


def _is_locked_out(username: str) -> bool:
    try:
        return bool(redis_client.exists(_lockout_key(username)))
    except redis.RedisError:
        app.logger.exception("Redis error while checking lockout")
        return False


def _record_failed_login(username: str) -> None:
    try:
        attempt_key = _attempt_key(username)
        count = redis_client.incr(attempt_key)

        if count == 1:
            redis_client.expire(attempt_key, LOCKOUT_SECONDS)

        if count >= MAX_ATTEMPTS:
            redis_client.setex(_lockout_key(username), LOCKOUT_SECONDS, "1")
            redis_client.delete(attempt_key)
    except redis.RedisError:
        app.logger.exception("Redis error while recording failed login")


def _clear_login_attempts(username: str) -> None:
    try:
        redis_client.delete(_attempt_key(username), _lockout_key(username))
    except redis.RedisError:
        app.logger.exception("Redis error while clearing login attempts")


@app.route("/register", methods=["GET", "POST"])
def register():
    form = RegisterForm()

    if form.validate_on_submit():
        username = form.username.data.strip().lower()

        if User.query.filter_by(username=username).first():
            flash("Username already exists.", "danger")
            return render_template("register.html", form=form), 409

        user = User(
            username=username,
            password_hash=argon2.hash_password(form.password.data),
            role="user",
        )
        db.session.add(user)
        db.session.commit()

        login_user(user)
        return redirect(url_for("dashboard"))

    return render_template("register.html", form=form)


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    form = LoginForm()

    if form.validate_on_submit():
        username = form.username.data.strip().lower()
        password = form.password.data

        if _is_locked_out(username):
            flash("Too many failed login attempts. Try again later.", "danger")
            return render_template("login.html", form=form), 429

        user = User.query.filter_by(username=username).first()

        # Important: verify against the STORED hash.
        # Do not hash the submitted password anew and compare to that new hash.
        valid = bool(user and argon2.verify_password(user.password_hash, password))

        if valid:
            _clear_login_attempts(username)
            login_user(user)
            flash("Logged in successfully.", "success")
            return redirect(url_for("dashboard"))

        _record_failed_login(username)

        # Generic message avoids username enumeration.
        flash("Invalid username or password.", "danger")

    return render_template("login.html", form=form)


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return f"Hello, {current_user.username}"
```

